css:
/* ==========================================================================
   MAX DEMOLITION AND EXCAVATION  ·  v2 "Night Shift"
   Palette from the Fast Quote tab spec:
   #FF6A00 primary orange · #0E0E0E background · #222222 panel · #FFFFFF text
   ========================================================================== */
:root{
  --bg:#0E0E0E; --bg-deep:#080808; --bg-band:#141414;
  --panel:#222222; --panel-lift:#2C2C2C; --panel-line:#333333; --line-soft:rgba(255,255,255,.1);
  --or:#FF6A00; --or-lift:#FF8A33; --or-deep:#D95800; --or-ink:#B84A00;
  --or-glow:rgba(255,106,0,.45); --or-ring:rgba(255,106,0,.3); --or-wash:rgba(255,106,0,.1);
  --white:#FFFFFF;
  --light:#F5F4F1; --light-2:#EAE8E3; --light-line:#DAD7D0;
  --t-body:#C8C8C8; --t-mute:#8E8E8E;
  --l-head:#0E0E0E; --l-body:#474747; --l-mute:#6A6A6A;
  --r:8px; --r-sm:4px;
  --wrap:1280px; --gut:clamp(18px,4vw,40px);
  --sec:clamp(64px,8.5vw,124px); --sec-tight:clamp(48px,6vw,86px);
  --t:.24s cubic-bezier(.2,.6,.3,1);
  --disp:'Anton','Barlow Condensed',Impact,sans-serif;
  --cond:'Barlow Condensed','Inter',system-ui,sans-serif;
}
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;scroll-behavior:smooth}
@media (prefers-reduced-motion:reduce){
  html{scroll-behavior:auto}
  *,*::before,*::after{animation-duration:.001ms!important;animation-iteration-count:1!important;transition-duration:.001ms!important}
}
body{margin:0;background:var(--bg);color:var(--t-body);font-family:'Inter',system-ui,-apple-system,'Segoe UI',Roboto,Arial,sans-serif;font-size:clamp(16px,.4vw + 15px,18.5px);line-height:1.6;-webkit-font-smoothing:antialiased}
img{max-width:100%;height:auto;display:block}
svg{width:18px;height:18px;flex-shrink:0}
.fa-solid,.fa-brands,.fa-regular{font-size:1em;line-height:1}
h1,h2,h3,h4{font-family:var(--disp);font-weight:400;color:var(--white);text-transform:uppercase;letter-spacing:.01em;margin:0}
h1{font-size:clamp(46px,6vw,92px);line-height:.98}
h2{font-size:clamp(32px,3.9vw,56px);line-height:1.04}
h3{font-size:clamp(21px,1.6vw,28px);line-height:1.12;letter-spacing:.02em}
h4{font-family:var(--cond);font-weight:700;font-size:15px;letter-spacing:.16em}
p{margin:0 0 1em}p:last-child{margin-bottom:0}
a{color:inherit;text-decoration:none}
ul{margin:0;padding:0;list-style:none}
::selection{background:var(--or);color:var(--white)}
:focus-visible{outline:3px solid var(--or);outline-offset:3px}
.skip{position:absolute;left:-9999px;top:0;z-index:999;background:var(--or);color:var(--white);font-weight:700;padding:12px 20px}
.skip:focus{left:8px;top:8px}
.container{width:100%;max-width:var(--wrap);margin-inline:auto;padding-inline:var(--gut)}
.reveal{animation:rvIn .8s both}
@keyframes rvIn{from{opacity:0;transform:translateY(26px)}to{opacity:1;transform:none}}

/* Two tone headings: the second phrase runs in orange, like the reference. */
.tt em,.hero h1 em{font-style:normal;color:var(--or)}
.section--light .tt em{color:var(--or)}

/* ---------- Shared section furniture ---------- */
.section{padding-block:var(--sec);position:relative;overflow-x:clip}
.section--tight{padding-block:var(--sec-tight)}
.section--dark{background:var(--bg)}
.section--deep{background:var(--bg-deep)}
.section--band{background:var(--bg-band)}
.section--light{background:var(--light);color:var(--l-body)}
.section--light h1,.section--light h2,.section--light h3{color:var(--l-head)}
/* Faint grit texture on the dark sections so the black is never flat. */
.grit::before{content:"";position:absolute;inset:0;pointer-events:none;z-index:0;opacity:.5;
  background:radial-gradient(1200px 500px at 85% -10%,rgba(255,106,0,.09),transparent 60%),radial-gradient(900px 400px at -10% 110%,rgba(255,106,0,.06),transparent 60%)}
.section > *{position:relative;z-index:1}

.eyebrow{font-family:var(--cond);font-weight:700;font-size:clamp(14px,1vw,16px);letter-spacing:.2em;text-transform:uppercase;color:var(--or-lift);margin:0 0 14px;display:flex;align-items:center;gap:12px}
.eyebrow::before{content:"";width:30px;height:3px;background:var(--or);flex:none}
.section--light .eyebrow{color:var(--or-ink)}
.lede{font-size:clamp(16.5px,.45vw + 15px,19px);line-height:1.62;max-width:62ch;color:var(--t-body)}
.section--light .lede{color:var(--l-body)}
.sec-head{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:28px;align-items:end;margin-bottom:clamp(36px,4.5vw,60px)}
.sec-head__text{min-width:0;max-width:74ch}
.sec-head h2{margin-bottom:18px}
@media (max-width:860px){.sec-head{grid-template-columns:minmax(0,1fr);align-items:start;gap:22px}}

/* ---------- Buttons ---------- */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:11px;font-family:var(--cond);font-weight:700;font-size:19px;letter-spacing:.08em;text-transform:uppercase;padding:15px 30px;min-height:56px;border:2px solid transparent;border-radius:var(--r-sm);cursor:pointer;transition:background var(--t),color var(--t),border-color var(--t),box-shadow var(--t),transform var(--t);text-align:center;line-height:1.1}
.btn i{font-size:.85em;transition:transform var(--t)}
.btn:hover i.fa-arrow-right{transform:translateX(4px)}
.btn--primary{background:var(--or);color:var(--white);border-color:var(--or);box-shadow:0 8px 24px -10px var(--or-glow)}
.btn--primary:hover{background:var(--or-lift);border-color:var(--or-lift);box-shadow:0 12px 30px -8px var(--or-glow);transform:translateY(-2px)}
.btn--primary:active{background:var(--or-deep);border-color:var(--or-deep);transform:none}
.btn--ghost{background:transparent;color:var(--white);border-color:var(--or)}
.btn--ghost:hover{background:var(--or);color:var(--white)}
.section--light .btn--ghost{color:var(--or-ink);border-color:var(--or)}
.section--light .btn--ghost:hover{background:var(--or);color:var(--white)}
.btn--on-dark{background:rgba(14,14,14,.4);color:var(--white);border-color:rgba(255,255,255,.4)}
.btn--on-dark:hover{background:var(--white);color:var(--bg);border-color:var(--white)}
.btn--black{background:var(--bg);color:var(--white);border-color:var(--bg)}
.btn--black:hover{background:var(--panel);border-color:var(--white)}
.btn--sm{padding:11px 20px;min-height:44px;font-size:16px}
.tlink{display:inline-flex;align-items:center;gap:10px;white-space:nowrap;font-family:var(--cond);font-weight:700;font-size:17px;letter-spacing:.1em;text-transform:uppercase;color:var(--or-lift);padding-block:8px;min-height:44px;border-bottom:2px solid var(--or);transition:gap var(--t)}
.tlink:hover{gap:16px}
.section--light .tlink{color:var(--or-ink)}

/* ---------- Utility bar ---------- */
.util{background:var(--bg-deep);border-bottom:1px solid var(--panel-line)}
.util .container{display:flex;align-items:center;justify-content:space-between;gap:18px;min-height:46px}
.util__facts{display:flex;align-items:center;gap:28px;flex-wrap:wrap}
.util__facts span{display:inline-flex;align-items:center;gap:9px;font-family:var(--cond);font-weight:700;font-size:15px;letter-spacing:.07em;text-transform:uppercase;color:var(--t-body);line-height:1.2}
.util__facts i{color:var(--or);font-size:13px}
.util__facts b{color:var(--white);font-weight:700}
.util__right{display:flex;align-items:stretch;gap:22px;flex-wrap:wrap;min-width:0;align-self:stretch}
.util__reviews{display:inline-flex;align-items:center;gap:10px;min-width:0;font-family:var(--cond);font-weight:700;font-size:15px;letter-spacing:.07em;text-transform:uppercase;color:var(--white);line-height:1.2}
.util__stars{display:inline-flex;align-items:center;gap:3px;color:var(--or);flex:none;filter:drop-shadow(0 0 6px rgba(255,106,0,.45))}
.util__stars i{font-size:12px}
.util__phone{display:inline-flex;align-items:center;gap:10px;font-family:var(--disp);font-size:21px;letter-spacing:.03em;color:var(--white)}
.util__phone i{color:var(--or);font-size:17px}
.util__phone:hover{color:var(--or-lift)}
.util__quote{display:inline-flex;align-items:center;gap:9px;padding:0 20px;background:var(--or);color:var(--white);font-family:var(--cond);font-weight:700;font-size:15px;letter-spacing:.1em;text-transform:uppercase;transition:background var(--t)}
.util__quote:hover{background:var(--or-lift)}
.util__quote i{font-size:12px}
/* The second fact repeats in the proof bar, so it gives way first. */
@media (max-width:1760px){.util__facts span:nth-child(2){display:none}}
@media (max-width:1100px){.util__facts{display:none}}
@media (max-width:860px){
  .util__facts,.util__phone,.util__quote{display:none}
  .util .container{justify-content:center;min-height:40px}
  .util__right{gap:0;justify-content:center}
  .util__reviews{font-size:14px;letter-spacing:.05em}
}
@media (max-width:360px){.util__reviews{font-size:13px;gap:8px}.util__stars i{font-size:11px}}

/* ---------- Header ---------- */
.hdr{position:sticky;top:0;z-index:80;background:rgba(14,14,14,.97);border-bottom:1px solid var(--panel-line)}
@supports (backdrop-filter:blur(8px)){.hdr{background:rgba(14,14,14,.9);backdrop-filter:blur(10px)}}
.hdr .container{display:flex;align-items:center;gap:20px;min-height:96px}
.hdr__logo{flex:none;display:block}
.hdr__logo img{width:180px;height:auto}
.navtoggle,.subtoggle,.qq__toggle{position:fixed;top:0;left:0;opacity:0;width:1px;height:1px;pointer-events:none}
.navwrap{margin-left:auto;display:flex;align-items:center}
.nav__list{display:flex;align-items:center;gap:2px}
.nav__row{display:flex;align-items:center}
.nav__link{position:relative;display:inline-flex;align-items:center;min-height:44px;padding:0 13px;font-family:var(--cond);font-weight:700;font-size:17px;letter-spacing:.09em;text-transform:uppercase;color:var(--white);transition:color var(--t);white-space:nowrap}
.nav__link::after{content:"";position:absolute;left:13px;right:13px;bottom:2px;height:3px;background:var(--or);transform:scaleX(0);transform-origin:left;transition:transform var(--t)}
.nav__link:hover{color:var(--or-lift)}
.nav__link:hover::after{transform:scaleX(1)}
.subcaret{display:inline-flex;align-items:center;justify-content:center;width:22px;min-height:44px;color:var(--t-mute);cursor:pointer}
.subcaret i{font-size:11px;transition:transform var(--t)}
.nav__panel,.nav__cta,.navclose,.navscrim{display:none}
@media (min-width:1241px){
  .nav__item--mega{position:static}
  .nav__panel{display:block;position:absolute;left:0;right:0;top:100%;background:var(--panel);border-top:3px solid var(--or);border-bottom:1px solid var(--panel-line);opacity:0;visibility:hidden;transform:translateY(-8px);transition:opacity var(--t),transform var(--t),visibility var(--t);box-shadow:0 30px 60px rgba(0,0,0,.55)}
  .nav__item--mega:hover .nav__panel,.nav__item--mega:focus-within .nav__panel{opacity:1;visibility:visible;transform:none}
}
.mega{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:28px 32px;max-width:var(--wrap);margin-inline:auto;padding:34px var(--gut) 28px}
.mega--areas{grid-template-columns:repeat(3,minmax(0,1fr))}
.mega--one{grid-template-columns:minmax(0,1fr)}
.mega__col{min-width:0}
.mega__col--wide .mega__list--areas{columns:2;column-gap:32px}
.mega__hub{display:flex;align-items:flex-start;gap:12px;padding-bottom:12px;margin-bottom:12px;border-bottom:1px solid var(--panel-line)}
.mega__hub i{color:var(--or);font-size:17px;margin-top:4px;width:20px;text-align:center;flex:none}
.mega__hub > span{font-family:var(--cond);font-weight:700;font-size:19px;letter-spacing:.05em;text-transform:uppercase;color:var(--white);line-height:1.15;min-width:0}
.mega__hub small{display:block;font-family:'Inter',sans-serif;font-weight:400;font-size:13px;letter-spacing:0;text-transform:none;color:var(--t-mute);margin-top:5px;line-height:1.45}
.mega__hub:hover > span{color:var(--or-lift)}
.mega__list li{margin-bottom:2px}
.mega__list a{display:block;font-size:14.5px;color:var(--t-body);padding:7px 10px;margin-left:-10px;min-height:36px;border-left:2px solid transparent;border-radius:0 var(--r-sm) var(--r-sm) 0;transition:color var(--t),border-color var(--t),background var(--t)}
.mega__list a:hover{color:var(--white);border-left-color:var(--or);background:rgba(255,255,255,.05)}
.mega__list--areas a small{display:block;font-size:12.5px;color:var(--t-mute);margin-top:3px;line-height:1.45}
.mega__label{font-family:var(--cond);font-weight:700;font-size:14px;letter-spacing:.2em;text-transform:uppercase;color:var(--or-lift);margin:0 0 12px}
.mega__rest a{color:var(--or-lift);font-weight:600}
.mega__rest i{margin-left:7px;font-size:11px}
.mega__foot{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:20px 32px;align-items:center;max-width:var(--wrap);margin-inline:auto;padding:20px var(--gut);border-top:1px solid var(--panel-line)}
.mega__foot > div:first-child{min-width:0}
.mega__railtitle{font-family:var(--cond);font-weight:700;font-size:19px;letter-spacing:.05em;text-transform:uppercase;color:var(--white);margin:0 0 6px}
.mega__railtext{font-size:14.5px;color:var(--t-mute);margin:0;max-width:72ch}
.mega__footact{display:flex;align-items:center;gap:18px;flex-wrap:wrap}
.mega__tel{display:inline-flex;align-items:center;gap:9px;min-height:44px;font-family:var(--disp);font-size:19px;letter-spacing:.03em;color:var(--white)}
.mega__tel i{color:var(--or)}
.hdr__cta{display:flex;align-items:center;gap:14px;flex:none}
.burger{display:none;align-items:center;justify-content:center;width:50px;height:50px;border:1px solid var(--panel-line);border-radius:var(--r-sm);color:var(--white);cursor:pointer;background:var(--panel)}
.burger i{font-size:19px}
@media (max-width:1240px){
  .hdr .container{min-height:84px}
  .hdr__logo img{width:156px}
  .burger{display:inline-flex}
  .hdr__cta .btn{display:none}
  .navscrim{display:block;position:fixed;inset:0;background:rgba(0,0,0,.72);opacity:0;visibility:hidden;transition:opacity var(--t),visibility var(--t);z-index:90}
  .nav{position:fixed;top:0;right:0;bottom:0;width:min(420px,88vw);background:var(--panel);border-left:3px solid var(--or);display:flex;flex-direction:column;z-index:95;overflow-y:auto;overscroll-behavior:contain;padding:22px 22px 40px;clip-path:inset(0 0 0 100%);pointer-events:none;transition:clip-path .3s cubic-bezier(.2,.6,.3,1)}
  .navtoggle:checked ~ .navwrap .nav{clip-path:inset(0 0 0 0);pointer-events:auto}
  .navtoggle:checked ~ .navwrap .navscrim{opacity:1;visibility:visible}
  .navclose{display:inline-flex;align-items:center;justify-content:center;align-self:flex-end;width:46px;height:46px;margin-bottom:10px;border:1px solid var(--panel-line);border-radius:var(--r-sm);color:var(--white);cursor:pointer}
  .nav__list{display:block}
  .nav__item{border-bottom:1px solid var(--panel-line)}
  .nav__row{justify-content:space-between}
  .nav__link{flex:1;padding:4px 0;min-height:52px;font-size:20px}
  .nav__link::after{display:none}
  .subcaret{width:52px;min-height:52px;border-left:1px solid var(--panel-line)}
  .nav__panel{display:block;max-height:0;overflow:hidden;transition:max-height .3s ease}
  .subtoggle:checked ~ .nav__panel{max-height:3200px}
  .subtoggle:checked ~ .nav__row .subcaret i{transform:rotate(180deg)}
  .mega{grid-template-columns:minmax(0,1fr);gap:22px;padding:4px 0 18px}
  .mega--areas,.mega--one{grid-template-columns:minmax(0,1fr)}
  .mega__col--wide .mega__list--areas{columns:1}
  .mega__foot{grid-template-columns:minmax(0,1fr);padding:16px 0;gap:14px}
  .nav__cta{display:flex;flex-direction:column;gap:12px;margin-top:26px}
  .nav__cta .btn{width:100%}
}
@media (max-width:420px){.hdr .container{gap:12px}.hdr__logo img{width:136px}}

/* ---------- Hero ---------- */
.hero{position:relative;background:var(--bg-deep);padding-block:clamp(54px,6.5vw,100px) clamp(70px,8vw,120px);overflow:hidden}
.hero__media{position:absolute;inset:0;z-index:0}
.hero__media img{width:100%;height:100%;object-fit:cover;object-position:62% 40%;filter:contrast(1.1) saturate(1.12);animation:heroZoom 22s ease-out both}
@keyframes heroZoom{from{transform:scale(1.08)}to{transform:scale(1)}}
.hero__media::after{content:"";position:absolute;inset:0;background:
  linear-gradient(90deg,rgba(8,8,8,.96) 0%,rgba(8,8,8,.86) 36%,rgba(8,8,8,.42) 66%,rgba(8,8,8,.62) 100%),
  linear-gradient(0deg,rgba(8,8,8,.95) 0%,rgba(8,8,8,0) 40%),
  radial-gradient(700px 420px at 72% 38%,rgba(255,106,0,.22),transparent 70%)}
/* Drifting dust, pure CSS and purely decorative. */
.dust{position:absolute;inset:0;z-index:1;pointer-events:none;overflow:hidden}
.dust span{position:absolute;bottom:-20px;width:5px;height:5px;border-radius:50%;background:radial-gradient(circle,#FFB070 0%,rgba(255,106,0,.6) 45%,transparent 70%);opacity:0;animation:drift 9s linear infinite}
.dust span:nth-child(1){left:52%;animation-delay:0s}
.dust span:nth-child(2){left:61%;animation-delay:1.6s;width:3px;height:3px}
.dust span:nth-child(3){left:70%;animation-delay:3.1s}
.dust span:nth-child(4){left:78%;animation-delay:4.4s;width:4px;height:4px}
.dust span:nth-child(5){left:86%;animation-delay:5.8s;width:3px;height:3px}
.dust span:nth-child(6){left:93%;animation-delay:7.2s}
.dust span:nth-child(7){left:66%;animation-delay:2.4s;width:2px;height:2px}
.dust span:nth-child(8){left:44%;animation-delay:6.4s;width:3px;height:3px}
@keyframes drift{0%{transform:translate(0,0);opacity:0}12%{opacity:.9}100%{transform:translate(-60px,-640px);opacity:0}}
.hero .container{position:relative;z-index:2}
.hero__grid{display:grid;grid-template-columns:minmax(0,1.14fr) minmax(0,.86fr);gap:clamp(32px,3.6vw,64px);align-items:center}
.hero__inner{min-width:0}
.hero h1{text-shadow:0 4px 30px rgba(0,0,0,.5)}
.hero h1 em{display:inline}
.hero__rule{width:110px;height:5px;background:var(--or);margin:26px 0 22px;box-shadow:0 0 18px var(--or-glow)}
.hero__lede{color:#E2E2E2;font-size:clamp(16.5px,.42vw + 15px,19px);max-width:56ch;margin:0 0 32px}
.hero__actions{display:flex;flex-wrap:wrap;gap:14px}
.hero__actions .btn{min-width:min(100%,220px)}
.btn--tel i{color:var(--or)}
.btn--tel:hover i{color:var(--white)}

.heroform{min-width:0;position:relative;background:rgba(20,20,20,.94);border:1px solid var(--panel-line);border-radius:var(--r);padding:clamp(24px,2.3vw,34px);box-shadow:0 30px 70px -20px rgba(0,0,0,.8),0 0 0 1px rgba(255,106,0,.08)}
.heroform::before{content:"";position:absolute;left:-1px;right:-1px;top:-1px;height:4px;background:var(--or);border-radius:var(--r) var(--r) 0 0;box-shadow:0 0 22px var(--or-glow)}
@supports (backdrop-filter:blur(6px)){.heroform{background:rgba(20,20,20,.82);backdrop-filter:blur(12px)}}
.heroform__eyebrow{font-family:var(--cond);font-weight:700;font-size:14px;letter-spacing:.22em;text-transform:uppercase;color:var(--or-lift);margin:0 0 8px}
.heroform__title{font-family:var(--disp);font-weight:400;font-size:clamp(26px,2.2vw,36px);line-height:1.04;text-transform:uppercase;color:var(--white);margin:0 0 8px}
.heroform__sub{font-size:14.5px;line-height:1.5;color:var(--t-mute);margin:0 0 22px}
.heroform .fgrid{gap:14px;margin-bottom:16px}
.heroform .field label{font-size:14px}
.heroform .field input,.heroform .field select{min-height:48px;padding:12px 14px}
.heroform .field textarea{min-height:82px;padding:12px 14px}
.heroform .btn{width:100%}
.heroform__fine{font-size:12.5px;line-height:1.5;color:var(--t-mute);margin:14px 0 0}
@media (max-width:1080px){.hero__grid{grid-template-columns:minmax(0,1fr)}.hero__lede{max-width:66ch}}
@media (max-width:760px){.hero__actions .btn{width:100%}.hero__media img{object-position:68% 40%}}

/* ---------- Proof bar (trust strip under the hero) ---------- */
.proof{background:var(--bg-deep);border-top:1px solid var(--panel-line);border-bottom:1px solid var(--panel-line);position:relative;z-index:3}
.proof::before{content:"";position:absolute;left:0;right:0;top:-1px;height:2px;background:linear-gradient(90deg,transparent,var(--or) 20%,var(--or) 80%,transparent);opacity:.8}
.proof .container{display:flex;align-items:stretch;flex-wrap:wrap}
.proof__item{display:flex;align-items:center;gap:16px;flex:1 1 220px;min-width:0;padding:24px 22px 24px 0;font-family:var(--cond);font-weight:700;font-size:clamp(15px,.3vw + 14px,18px);letter-spacing:.07em;text-transform:uppercase;line-height:1.2;color:var(--white)}
.proof__item + .proof__item{border-left:1px solid var(--panel-line);padding-left:22px}
.proof__item i{font-size:30px;color:var(--or);flex:none;width:36px;text-align:center;filter:drop-shadow(0 0 10px rgba(255,106,0,.35))}
@media (max-width:860px){
  .proof__item{flex:1 1 100%;padding:15px 0}
  .proof__item + .proof__item{border-left:0;border-top:1px solid var(--panel-line);padding-left:0}
  .proof__item i{font-size:24px}
}

/* ---------- Services ---------- */
.svc__grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,2fr);gap:clamp(30px,4vw,60px);align-items:start;margin-bottom:clamp(44px,5vw,72px)}
.svc__intro{min-width:0;position:sticky;top:130px}
.svc__intro h2{margin-bottom:18px;font-size:clamp(32px,3.1vw,48px)}
.fleet__text h2,.cov__text h2,.conv__text h2{margin-bottom:20px}
.svc__intro .tlink{margin-top:24px}
.capstrip{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;min-width:0}
.capstrip__item{margin:0;min-width:0;background:var(--white);border:1px solid var(--light-line);border-radius:var(--r);overflow:hidden;box-shadow:0 10px 30px -18px rgba(0,0,0,.35);transition:transform var(--t),box-shadow var(--t),border-color var(--t)}
.capstrip__item:hover{transform:translateY(-5px);border-color:var(--or);box-shadow:0 22px 40px -18px rgba(255,106,0,.45)}
.capstrip__media{overflow:hidden;position:relative}
.capstrip__media::after{content:"";position:absolute;left:0;right:0;bottom:0;height:4px;background:var(--or);transform:scaleX(0);transform-origin:left;transition:transform .35s ease}
.capstrip__item:hover .capstrip__media::after{transform:scaleX(1)}
.capstrip__item img{width:100%;aspect-ratio:4/3;object-fit:cover;transition:transform .6s ease}
.capstrip__item:hover img{transform:scale(1.06)}
.capstrip__item figcaption{padding:16px 18px 20px}
.capstrip__item figcaption b{display:block;font-family:var(--cond);font-weight:800;font-size:clamp(18px,1.3vw,21px);letter-spacing:.03em;text-transform:uppercase;color:var(--l-head);line-height:1.12}
.capstrip__item figcaption span{display:block;margin-top:8px;font-size:14px;color:var(--l-mute);line-height:1.5}
@media (max-width:1180px){.svc__grid{grid-template-columns:minmax(0,1fr)}.svc__intro{position:static}}
@media (max-width:900px){.capstrip{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:480px){.capstrip{grid-template-columns:minmax(0,1fr)}}

.fams{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;counter-reset:fam}
.fam{position:relative;min-width:0;display:flex;flex-direction:column;background:var(--bg);border:1px solid var(--panel);border-radius:var(--r);padding:28px 24px 22px;overflow:hidden;counter-increment:fam;transition:border-color var(--t),transform var(--t),box-shadow var(--t)}
.fam::before{content:"0" counter(fam);position:absolute;top:12px;right:16px;font-family:var(--disp);font-size:clamp(48px,3.8vw,68px);line-height:.9;color:rgba(255,255,255,.06);pointer-events:none}
.fam::after{content:"";position:absolute;left:0;top:0;bottom:0;width:4px;background:var(--or);transform:scaleY(0);transform-origin:top;transition:transform .35s ease}
.fam:hover{border-color:var(--or);transform:translateY(-4px);box-shadow:0 22px 40px -20px rgba(255,106,0,.55)}
.fam:hover::after{transform:scaleY(1)}
.fam__head{display:flex;align-items:flex-start;gap:14px;margin-bottom:16px;position:relative;z-index:1;padding-right:44px}
.fam__head > div{min-width:0}
.fam__icon{display:inline-flex;align-items:center;justify-content:center;flex:none;width:50px;height:50px;border-radius:50%;background:var(--or);color:var(--white);box-shadow:0 0 0 5px rgba(255,106,0,.15)}
.fam__icon i{font-size:19px}
.section--light .fam__title,.fam__title{font-family:var(--cond);font-weight:800;font-size:clamp(20px,1.45vw,24px);line-height:1.08;margin-bottom:6px;color:var(--white);letter-spacing:.02em}
.fam__count{display:block;white-space:nowrap;font-size:12.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--or-lift)}
.fam__sum{font-size:15px;line-height:1.55;color:var(--t-body);margin-bottom:18px}
.fam__list{border-top:1px solid var(--panel-line);padding-top:16px;margin-bottom:14px;display:flex;flex-direction:column;gap:9px}
.fam__list li{position:relative;padding-left:18px;font-size:14.5px;line-height:1.45;color:var(--t-body)}
.fam__list li::before{content:"";position:absolute;left:0;top:.62em;width:7px;height:2px;background:var(--or)}
.fam__also{font-size:13px;color:var(--t-mute);margin-bottom:18px}
.fam__go{margin-top:auto;display:inline-flex;align-items:center;gap:10px;min-height:44px;font-family:var(--cond);font-weight:700;font-size:16px;letter-spacing:.1em;text-transform:uppercase;color:var(--or-lift);transition:gap var(--t)}
.fam__go:hover{gap:16px}
@media (max-width:1180px){.fams{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:620px){.fams{grid-template-columns:minmax(0,1fr)}}
.svc__foot{display:flex;flex-wrap:wrap;gap:16px;margin-top:clamp(36px,4vw,56px)}

/* ---------- Capability statement ---------- */
.cap__grid{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,1fr);gap:clamp(36px,5vw,76px);align-items:center}
.cap__media{position:relative;min-width:0}
.cap__media img{width:100%;aspect-ratio:16/11;object-fit:cover;border-radius:var(--r);filter:contrast(1.08)}
.cap__keyline{position:absolute;inset:-14px -14px auto auto;width:132px;height:132px;border-top:4px solid var(--or);border-right:4px solid var(--or);border-radius:0 var(--r) 0 0;pointer-events:none;filter:drop-shadow(0 0 10px rgba(255,106,0,.5))}
.cap__stat{position:absolute;left:-1px;bottom:-1px;max-width:min(360px,86%);background:var(--or);color:var(--white);padding:22px 24px;border-radius:0 var(--r) 0 var(--r);box-shadow:0 20px 40px -12px rgba(255,106,0,.55)}
.cap__stat strong{display:block;font-family:var(--disp);font-weight:400;font-size:clamp(22px,1.7vw,28px);letter-spacing:.03em;text-transform:uppercase;line-height:1.05;margin-bottom:7px}
.cap__stat span{display:block;font-size:14px;line-height:1.45;color:rgba(255,255,255,.92)}
.cap__text{min-width:0}
.cap__text h2{margin-bottom:20px}
.cap__list{display:flex;flex-direction:column;gap:16px;margin:28px 0 32px}
.cap__list li{display:flex;gap:14px;align-items:flex-start;font-size:16px;line-height:1.55}
.cap__list i{display:inline-flex;align-items:center;justify-content:center;width:26px;height:26px;border-radius:50%;background:var(--or-wash);border:1px solid var(--or);color:var(--or);font-size:11px;margin-top:1px;flex:none}
@media (max-width:980px){.cap__grid{grid-template-columns:minmax(0,1fr)}.cap__keyline{width:92px;height:92px}}

/* ---------- Statistics ---------- */
.stats{background:var(--bg-band);position:relative}
.stats .container{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}
.stats__item{min-width:0;padding:clamp(28px,3vw,40px) clamp(18px,2vw,28px);background:var(--panel);border:1px solid var(--panel-line);border-radius:var(--r);position:relative;overflow:hidden;transition:border-color var(--t),transform var(--t)}
.stats__item::after{content:"";position:absolute;right:-60px;bottom:-60px;width:160px;height:160px;border-radius:50%;background:radial-gradient(circle,rgba(255,106,0,.25),transparent 70%);transition:transform .4s ease}
.stats__item:hover{border-color:var(--or);transform:translateY(-4px)}
.stats__item:hover::after{transform:scale(1.5)}
.stats__fig{display:block;font-family:var(--disp);font-size:clamp(56px,6vw,96px);line-height:.92;color:var(--or);margin-bottom:12px;text-shadow:0 0 30px rgba(255,106,0,.35)}
.stats__lab{display:block;font-family:var(--cond);font-weight:800;font-size:clamp(17px,1.15vw,21px);letter-spacing:.07em;text-transform:uppercase;color:var(--white);line-height:1.15;margin-bottom:8px}
.stats__sub{display:block;font-size:13.5px;line-height:1.5;color:var(--t-mute);position:relative;z-index:1}
@media (max-width:980px){.stats .container{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:520px){.stats .container{grid-template-columns:minmax(0,1fr)}}

/* ---------- Who we work with ---------- */
.who{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;counter-reset:who}
.who__card{min-width:0;position:relative;background:var(--white);border:1px solid var(--light-line);border-radius:var(--r);padding:34px 30px 30px;counter-increment:who;transition:border-color var(--t),transform var(--t),box-shadow var(--t)}
.who__card::before{content:"0" counter(who);position:absolute;top:14px;right:20px;font-family:var(--disp);font-size:clamp(52px,4.4vw,74px);line-height:1;color:rgba(14,14,14,.06)}
.who__card:hover{border-color:var(--or);transform:translateY(-4px);box-shadow:0 22px 40px -22px rgba(255,106,0,.55)}
.who__card > i{display:inline-flex;align-items:center;justify-content:center;width:58px;height:58px;border-radius:50%;background:var(--or);color:var(--white);font-size:22px;margin-bottom:20px;box-shadow:0 0 0 6px rgba(255,106,0,.14)}
.who__card h3{margin-bottom:12px}
.who__card h3::after{content:"";display:block;width:44px;height:3px;background:var(--or);margin-top:12px}
.who__card p{font-size:15.5px;line-height:1.6;color:var(--l-body);margin:0}
@media (max-width:900px){.who{grid-template-columns:minmax(0,1fr)}}

/* ---------- Plant and haulage ---------- */
.fleet__grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.02fr);gap:clamp(36px,5vw,76px);align-items:center}
.fleet__media{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;min-width:0}
.fleet__media img{width:100%;height:100%;object-fit:cover;aspect-ratio:4/5;border-radius:var(--r);border:1px solid var(--panel-line);box-shadow:0 24px 50px -24px rgba(0,0,0,.9);transition:transform .5s ease,border-color var(--t)}
.fleet__media img:nth-child(2){margin-top:44px}
.fleet__media img:hover{transform:scale(1.02);border-color:var(--or)}
.fleet__text{min-width:0}
.fleet__cols{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-top:30px}
.fleet__cols > div{min-width:0;padding:18px 20px;background:var(--panel);border:1px solid var(--panel-line);border-radius:var(--r);transition:border-color var(--t),background var(--t)}
.fleet__cols > div:hover{background:var(--panel-lift);border-color:var(--or)}
.fleet__cols b{display:block;font-family:var(--cond);font-weight:800;font-size:18px;letter-spacing:.06em;text-transform:uppercase;color:var(--white);margin-bottom:7px}
.fleet__cols b::after{content:"";display:block;width:28px;height:2px;background:var(--or);margin-top:7px}
.fleet__cols span{display:block;font-size:14px;line-height:1.5;color:var(--t-mute)}
@media (max-width:980px){.fleet__grid{grid-template-columns:minmax(0,1fr)}.fleet__media img{aspect-ratio:1/1}.fleet__media img:nth-child(2){margin-top:0}}
@media (max-width:560px){.fleet__cols{grid-template-columns:minmax(0,1fr)}}

/* ---------- Single focus CTA, as the orange band from the reference ---------- */
.onecta-band{position:relative;background:var(--or);overflow:hidden;padding-block:0}
.onecta-band::before{content:"";position:absolute;inset:0;pointer-events:none;opacity:.55;
  background:
   radial-gradient(circle at 12% 18%,rgba(0,0,0,.28) 0 2px,transparent 3px) 0 0/38px 41px,
   radial-gradient(circle at 70% 60%,rgba(0,0,0,.22) 0 1.5px,transparent 2.5px) 0 0/27px 31px,
   radial-gradient(900px 300px at 100% 100%,rgba(0,0,0,.28),transparent 70%),
   radial-gradient(600px 260px at 0% 0%,rgba(255,255,255,.12),transparent 70%)}
.onecta{position:relative;display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);min-height:440px}
.onecta__media{position:relative;min-width:0;margin-left:calc(var(--gut) * -1)}
.onecta__media img{width:100%;height:100%;object-fit:cover;filter:contrast(1.08) saturate(1.1);
  clip-path:polygon(0 0,100% 0,84% 100%,0 100%)}
.onecta__media::after{content:"";position:absolute;inset:0;clip-path:polygon(84% 0,100% 0,84% 100%,68% 100%);background:var(--bg);opacity:.9}
.onecta__body{position:relative;z-index:2;min-width:0;padding:clamp(40px,5vw,72px) 0 clamp(40px,5vw,72px) clamp(10px,2vw,30px);color:var(--bg)}
.onecta__title{font-size:clamp(32px,3.4vw,52px);line-height:1.02;margin:0 0 18px;color:var(--bg)}
.onecta__title em{display:inline;font-style:normal;color:var(--white)}
.onecta__lede{font-size:clamp(16px,.4vw + 15px,18.5px);line-height:1.6;color:#1E1007;margin:0 0 24px;max-width:58ch;font-weight:500}
.onecta__chips{display:flex;flex-wrap:wrap;gap:8px;margin:0 0 28px}
.onecta__chips li{display:inline-flex;align-items:center;gap:9px;white-space:nowrap;padding:9px 14px;background:rgba(14,14,14,.9);border-radius:999px;font-family:var(--cond);font-weight:700;font-size:14.5px;letter-spacing:.06em;text-transform:uppercase;color:var(--white);line-height:1.2}
.onecta__chips i{color:var(--or);font-size:13px}
.onecta__act{display:flex;flex-wrap:wrap;align-items:center;gap:22px;margin-bottom:16px}
.onecta__tel{display:inline-flex;align-items:center;gap:11px;min-height:44px;font-family:var(--disp);font-size:clamp(24px,1.7vw,30px);letter-spacing:.02em;color:var(--bg);transition:color var(--t)}
.onecta__tel i{font-size:.7em}
.onecta__tel:hover{color:var(--white)}
.onecta__note{font-size:14px;line-height:1.5;color:#2A1608;margin:0;font-weight:500}
@media (max-width:980px){
  .onecta{grid-template-columns:minmax(0,1fr);min-height:0}
  .onecta__media{margin-inline:calc(var(--gut) * -1)}
  .onecta__media img{aspect-ratio:16/9;clip-path:polygon(0 0,100% 0,100% 86%,0 100%)}
  .onecta__media::after{display:none}
  .onecta__body{padding:30px 0 56px}
}
@media (max-width:560px){.onecta__act .btn{width:100%}}
@media (max-width:520px){.onecta__chips li{white-space:normal;width:100%;border-radius:var(--r-sm)}}

/* ---------- Process ---------- */
.steps{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:18px;counter-reset:step}
.step{min-width:0;position:relative;padding:4px 6px 0 0;counter-increment:step}
.step__num{position:relative;display:flex;align-items:center;justify-content:center;width:84px;height:84px;border-radius:50%;background:var(--or);color:var(--white);margin-bottom:20px;box-shadow:0 0 0 8px rgba(255,106,0,.14),0 16px 30px -10px rgba(255,106,0,.6);transition:transform var(--t)}
.step__num i{font-size:30px}
.step__num::after{content:"0" counter(step);position:absolute;top:-6px;right:-10px;min-width:34px;height:34px;padding:0 6px;border-radius:999px;background:var(--bg);color:var(--white);font-family:var(--disp);font-size:16px;display:flex;align-items:center;justify-content:center;border:2px solid var(--light)}
.step:hover .step__num{transform:translateY(-4px) rotate(-6deg)}
/* Connector arrow between the steps on wide screens. */
.step:not(:last-child)::after{content:"";position:absolute;top:40px;left:106px;right:-6px;height:2px;background:repeating-linear-gradient(90deg,var(--or) 0 8px,transparent 8px 14px);opacity:.75}
.step:not(:last-child)::before{content:"";position:absolute;top:35px;right:-8px;border:6px solid transparent;border-left:9px solid var(--or)}
.step h3{margin-bottom:12px}
.step h3::after{content:"";display:block;width:36px;height:3px;background:var(--or);margin-top:11px}
.step p{font-size:15px;line-height:1.55;color:var(--l-body);margin:0}
@media (max-width:1180px){.steps{grid-template-columns:repeat(3,minmax(0,1fr));gap:34px 22px}.step::after,.step::before{display:none}}
@media (max-width:820px){.steps{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:520px){.steps{grid-template-columns:minmax(0,1fr)}}

/* ---------- Coverage with the harbour skyline ---------- */
.cov{background:linear-gradient(180deg,#0E0E0E 0%,#121212 60%,#0B0B0B 100%)}
.skyline{position:absolute;right:0;bottom:0;z-index:0!important;width:min(1100px,100%);height:auto;aspect-ratio:1100/360;pointer-events:none;opacity:.6}
.cov__grid{display:grid;grid-template-columns:minmax(0,.85fr) minmax(0,1.15fr);gap:clamp(36px,5vw,72px);align-items:start}
.cov__text{min-width:0}
.cov__note{margin-top:22px;padding:18px 20px;font-size:15px;line-height:1.55;background:rgba(34,34,34,.85);border-left:3px solid var(--or);border-radius:0 var(--r) var(--r) 0;color:var(--t-body)}
.areas{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;min-width:0}
.area{min-width:0;background:rgba(26,26,26,.88);border:1px solid var(--panel-line);border-radius:var(--r);padding:20px 20px 16px;transition:border-color var(--t),background var(--t),transform var(--t)}
@supports (backdrop-filter:blur(4px)){.area{background:rgba(26,26,26,.72);backdrop-filter:blur(6px)}}
.area:hover{border-color:var(--or);transform:translateY(-3px)}
.area__hub{display:flex;gap:12px;align-items:flex-start;min-width:0}
.area__hub > i{color:var(--or);font-size:17px;margin-top:3px;flex:none;width:18px;text-align:center;filter:drop-shadow(0 0 8px rgba(255,106,0,.5))}
.area__hub > span{min-width:0}
.area__hub b{display:block;font-family:var(--cond);font-weight:800;font-size:19px;letter-spacing:.04em;text-transform:uppercase;color:var(--white);line-height:1.15;margin-bottom:6px}
.area__hub:hover b{color:var(--or-lift)}
.area__hub span span{display:block;font-size:13.5px;line-height:1.5;color:var(--t-mute);overflow-wrap:anywhere}
.area__links{display:flex;flex-wrap:wrap;gap:8px;margin-top:14px;padding-top:14px;border-top:1px solid var(--panel-line)}
.area__svc{display:inline-flex;align-items:center;min-height:36px;padding:7px 12px;font-size:12.5px;font-weight:500;color:var(--t-body);border:1px solid var(--panel-line);border-radius:999px;transition:color var(--t),border-color var(--t),background var(--t)}
.area__svc:hover{color:var(--white);border-color:var(--or);background:var(--or-wash)}
@media (max-width:1080px){.cov__grid{grid-template-columns:minmax(0,1fr)}}
@media (max-width:620px){.areas{grid-template-columns:minmax(0,1fr)}}

/* ---------- Conversion ---------- */
.conv{background:var(--bg-deep);border-top:1px solid var(--panel-line)}
.conv__grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(36px,5vw,72px);align-items:start}
.conv__text{min-width:0}
.conv__points{display:flex;flex-direction:column;gap:14px;margin:28px 0}
.conv__points li{display:flex;gap:14px;align-items:flex-start;font-size:16px;line-height:1.55}
.conv__points i{display:inline-flex;align-items:center;justify-content:center;width:26px;height:26px;border-radius:50%;background:var(--or);color:var(--white);font-size:11px;margin-top:1px;flex:none}
.conv__call{margin-top:30px;padding:24px 26px;background:var(--panel);border:1px solid var(--panel-line);border-left:4px solid var(--or);border-radius:0 var(--r) var(--r) 0}
.conv__call span{display:block;font-family:var(--cond);font-weight:700;font-size:14px;letter-spacing:.2em;text-transform:uppercase;color:var(--t-mute);margin-bottom:8px}
.conv__call a{font-family:var(--disp);font-size:clamp(34px,3.4vw,50px);line-height:1;color:var(--white);overflow-wrap:anywhere}
.conv__call a:hover{color:var(--or-lift)}
.formcard{min-width:0;position:relative;background:var(--panel);border:1px solid var(--panel-line);border-radius:var(--r);padding:clamp(26px,3vw,40px);box-shadow:0 30px 60px -30px rgba(255,106,0,.35)}
.formcard::before{content:"";position:absolute;left:-1px;right:-1px;top:-1px;height:4px;background:var(--or);border-radius:var(--r) var(--r) 0 0}
.formcard h3{font-size:clamp(26px,2.2vw,34px);margin-bottom:10px}
.formcard .sub{font-size:15px;color:var(--t-mute);margin-bottom:26px}
.fgrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;margin-bottom:22px}
.field{display:flex;flex-direction:column;gap:8px;min-width:0}
.field--full{grid-column:1/-1}
.field label{font-family:var(--cond);font-weight:700;font-size:15px;letter-spacing:.1em;text-transform:uppercase;color:var(--white);display:inline-flex;align-items:center;gap:4px;min-height:24px}
.req{color:var(--or)}
