.field select{appearance:none;-webkit-appearance:none;padding-right:42px;cursor:pointer;background-image:url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 12 8'%3E%3Cpath fill='%23FF6A00' d='M0.8 1.4h10.4L6 7.2z'/%3E%3C/svg%3E");background-repeat:no-repeat;background-position:right 16px center;background-size:12px 8px}
.field textarea{min-height:120px;resize:vertical;line-height:1.55}
.field input::placeholder,.field textarea::placeholder{color:var(--t-mute)}
.field input:focus,.field select:focus,.field textarea:focus{outline:none;border-color:var(--or);box-shadow:0 0 0 3px var(--or-ring)}
.field select option{background:#222222;color:#FFFFFF}
.fine{font-size:13.5px;color:var(--t-mute);margin:16px 0 0;line-height:1.55}
