/* ---------- Footer ---------- */
/* ==========================================================================
   PROJECTS  ·  completed job cards
   Two per row on desktop, one on a phone. The status chip sits on the photo,
   the specs are a definition list so the labels stay readable to a screen
   reader, and the call to action is a <label for> like every other quote
   button on the site, so it opens the drawer in the global header.
   ========================================================================== */
.projgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,380px),1fr));gap:30px}
.proj{display:flex;flex-direction:column;background:var(--panel);border:1px solid var(--light-line);
  border-radius:var(--r);overflow:hidden}
.section--light .proj{background:#fff}
.proj__media{position:relative;line-height:0}
.proj__media img{width:100%;height:auto;aspect-ratio:16/10;object-fit:cover;display:block}
.proj__status{position:absolute;top:14px;left:14px;display:inline-flex;align-items:center;gap:7px;
  padding:7px 14px;border-radius:999px;background:rgba(14,14,14,.86);color:#fff;
  font-family:var(--cond);font-weight:700;font-size:12.5px;letter-spacing:.14em;text-transform:uppercase}
.proj__status::before{content:"";width:8px;height:8px;border-radius:50%;background:#35C759}
.proj__body{display:flex;flex-direction:column;flex:1;padding:24px 26px 26px}
.proj__body h3{margin:0 0 8px}
.proj__loc{display:flex;align-items:center;gap:8px;margin:0 0 14px;font-size:14px;color:var(--l-mute)}
.proj__loc i{color:var(--or)}
.proj__body > p{margin:0 0 20px;font-size:15.5px;line-height:1.62;color:var(--l-body)}
.proj__specs{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px 18px;margin:0 0 22px;
  padding:18px 0 0;border-top:1px solid var(--light-line)}
.proj__specs > div{min-width:0}
.proj__specs dt{font-family:var(--cond);font-weight:700;font-size:12px;letter-spacing:.16em;
  text-transform:uppercase;color:var(--l-mute);margin:0 0 3px}
.proj__specs dd{margin:0;font-family:var(--cond);font-weight:700;font-size:21px;color:var(--ink)}
.proj__cta{margin-top:auto;align-self:flex-start}
@media (max-width:520px){.proj__specs{grid-template-columns:repeat(2,minmax(0,1fr))}
  .proj__body{padding:20px}}

.ftr{background:var(--bg-deep);border-top:3px solid var(--or);padding-block:clamp(52px,6vw,84px) 0;position:relative}
.ftr::before{content:"";position:absolute;left:0;right:0;top:-3px;height:3px;box-shadow:0 0 26px 2px var(--or-glow);pointer-events:none}
.ftr__top{display:grid;grid-template-columns:1.55fr repeat(4,minmax(0,1fr)) 1.45fr;gap:40px 30px;padding-bottom:clamp(34px,3.6vw,46px)}
.ftr__top > div{min-width:0}
.ftr__logo img{width:190px;height:auto;margin-bottom:20px}
.ftr__about{font-size:14.5px;line-height:1.6;color:var(--t-mute);margin-bottom:22px}
.social{display:flex;gap:10px}
.social a{display:inline-flex;align-items:center;justify-content:center;width:44px;height:44px;border-radius:50%;border:1px solid var(--panel-line);color:var(--white);transition:background var(--t),border-color var(--t)}
.social a:hover{background:var(--or);border-color:var(--or)}
.ftr h4{color:var(--white);margin:0 0 18px;padding-bottom:12px;border-bottom:1px solid var(--panel-line)}
.ftr ul li{margin-bottom:2px}
.ftr ul a{display:block;font-size:14px;line-height:1.45;color:var(--t-mute);padding:7px 0;min-height:34px;transition:color var(--t),padding-left var(--t)}
