.ftr__contact > div{margin-bottom:15px}
.ftr__contact span{display:block;font-family:var(--cond);font-weight:700;font-size:12.5px;letter-spacing:.18em;text-transform:uppercase;color:var(--t-mute);margin-bottom:5px}
.ftr__contact a{font-size:15px;color:var(--white);display:inline-block;min-height:30px}
.ftr__em{white-space:nowrap}
.ftr__ph{font-family:var(--cond);font-weight:700;font-size:21px;letter-spacing:.01em;white-space:nowrap}
.ftr__contact a:hover{color:var(--or-lift)}
.ftr__contact p{font-size:14px;line-height:1.5;color:var(--t-body);margin:0}
/* Areas we serve, one full width row rather than a column.
   Fourteen stacked items forced a seventh column on the grid above, which is
