.ftr__areas{padding-bottom:clamp(30px,3.2vw,42px)}
.ftr__areas h4{margin-bottom:16px}
.ftr ul.ftr__arealist{display:flex;flex-wrap:wrap;gap:10px;margin:0;padding:0;list-style:none}
.ftr ul.ftr__arealist li{margin:0}
.ftr ul.ftr__arealist a{display:inline-flex;align-items:center;justify-content:center;
  min-height:38px;padding:9px 20px;border:1px solid var(--panel-line);border-radius:999px;
  font-size:13.5px;line-height:1.25;color:var(--t-mute);white-space:nowrap;
  transition:color var(--t),border-color var(--t),background var(--t)}
.ftr ul.ftr__arealist a:hover{color:var(--white);border-color:var(--or);
  background:rgba(255,106,0,.1);padding-left:20px}
.ftr ul.ftr__arealist a.ftr__areaall{color:var(--or-lift);border-color:rgba(255,106,0,.45)}
@media (max-width:620px){.ftr ul.ftr__arealist a{padding:9px 16px;font-size:13px}}
.ftr__legal{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:16px 26px;padding-block:22px;border-top:1px solid var(--panel-line)}
.ftr__legal p{font-size:13.5px;color:var(--t-mute);margin:0}
.ftr__legal nav{display:flex;flex-wrap:wrap;gap:20px}
.ftr__legal nav a{font-size:13.5px;color:var(--t-mute);min-height:34px;display:inline-flex;align-items:center}
.ftr__legal nav a:hover{color:var(--or-lift)}
.ftr__built{display:inline-flex;align-items:center;gap:9px;font-size:13.5px;color:var(--t-mute);margin-left:auto}
.ftr__built img{width:22px;height:22px;border-radius:6px}
.ftr__built b{color:var(--or-lift);font-weight:600}
@media (max-width:1400px){.ftr__top{grid-template-columns:1.5fr repeat(3,minmax(0,1fr));}
  .ftr__contact{grid-column:2/-1;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0 24px;align-items:start}
