  .ftr__contact{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:480px){.ftr__top{grid-template-columns:minmax(0,1fr)}
  .ftr__contact{grid-template-columns:minmax(0,1fr)}}

/* ==========================================================================
   GET A FAST QUOTE side tab  (spec: 60px closed, 80-90px hover, extended
   state with icons, fixed right and vertically centred, 8px radius, glow)
   ========================================================================== */
.qq__dock{position:fixed;right:0;top:50vh;transform:translateY(-50%);z-index:70;max-height:calc(100vh - 24px);transition:opacity var(--t),visibility var(--t)}
.xtab{position:relative;display:flex;align-items:stretch;min-height:300px;cursor:pointer;border-radius:var(--r) 0 0 var(--r);filter:drop-shadow(0 10px 22px rgba(0,0,0,.55));transition:filter var(--t)}
.xtab__machine{position:absolute;right:-6px;bottom:calc(100% - 46px);width:118px;max-width:none;height:auto;pointer-events:none;z-index:3;transform-origin:85% 100%;transition:transform .45s cubic-bezier(.3,1.4,.5,1)}
/* The extended column, hidden at rest, slides out to the left on hover. */
.xtab__ext{position:absolute;right:100%;top:50%;transform:translateY(-50%);width:0;max-height:calc(100vh - 40px);overflow:hidden;background:#141414;border:1px solid transparent;border-right:0;border-radius:var(--r) 0 0 var(--r);display:flex;flex-direction:column;justify-content:center;gap:18px;padding-block:18px;transition:width .35s cubic-bezier(.2,.7,.3,1),border-color var(--t)}
.xtab__ext span{display:flex;flex-direction:column;align-items:center;gap:6px;width:118px;padding:0 10px;text-align:center;font-family:var(--cond);font-weight:700;font-size:13.5px;letter-spacing:.06em;text-transform:uppercase;line-height:1.15;color:var(--white);opacity:0;transform:translateX(10px);transition:opacity .25s ease,transform .25s ease}
.xtab__ext i{font-size:24px;color:var(--or);filter:drop-shadow(0 0 8px rgba(255,106,0,.55))}
.xtab__body{position:relative;width:60px;display:flex;flex-direction:column;background:linear-gradient(180deg,#151515 0%,#0E0E0E 62%);border:1px solid #2A2A2A;border-right:0;border-radius:var(--r) 0 0 var(--r);overflow:hidden;transition:width .3s cubic-bezier(.2,.7,.3,1),box-shadow var(--t),border-color var(--t)}
.xtab__body::before{content:"";position:absolute;inset:0;pointer-events:none;
  background:radial-gradient(circle at 30% 70%,rgba(255,106,0,.35) 0 1px,transparent 2px) 0 0/9px 11px,radial-gradient(circle at 70% 30%,rgba(255,106,0,.25) 0 1px,transparent 2px) 0 0/13px 7px;
  -webkit-mask:linear-gradient(180deg,transparent 52%,#000 74%);mask:linear-gradient(180deg,transparent 52%,#000 74%)}
.xtab__text{flex:1;display:flex;align-items:center;justify-content:center;padding-top:26px;writing-mode:vertical-rl;font-family:var(--disp);font-size:25px;letter-spacing:.05em;text-transform:uppercase;color:var(--white);white-space:nowrap;position:relative;z-index:1}
.xtab__text em{font-style:normal;color:var(--or);padding-inline:.24em}
.xtab__go{position:relative;z-index:1;display:flex;align-items:center;justify-content:center;height:62px;background:var(--or);color:var(--white);font-size:21px;
  clip-path:polygon(0 14px,10% 6px,22% 12px,36% 2px,50% 10px,62% 0,76% 9px,88% 3px,100% 11px,100% 100%,0 100%)}
.xtab__go i{transition:transform var(--t)}
.qq__dock:hover .xtab,.xtab:focus-visible{filter:drop-shadow(0 0 18px rgba(255,106,0,.55)) drop-shadow(0 10px 22px rgba(0,0,0,.55))}
.qq__dock:hover .xtab__body,.xtab:focus-visible .xtab__body{width:84px;border-color:var(--or)}
.qq__dock:hover .xtab__ext,.xtab:focus-visible .xtab__ext{width:118px;border-color:var(--or)}
.qq__dock:hover .xtab__ext span,.xtab:focus-visible .xtab__ext span{opacity:1;transform:none;transition-delay:.15s}
.qq__dock:hover .xtab__machine,.xtab:focus-visible .xtab__machine{transform:rotate(-7deg) translateY(-4px)}
.qq__dock:hover .xtab__go i{transform:translateX(4px)}
/* Phone: a compact version of the same tab, as in the mobile panel of the spec. */
@media (max-width:860px){
  .qq__dock{transform:translateY(-50%)}
  .xtab{min-height:214px}
  .xtab__body{width:44px}
  .xtab__text{font-size:18px;padding-top:18px}
  .xtab__go{height:44px;font-size:16px}
  .xtab__machine{width:80px;max-width:none;bottom:calc(100% - 30px)}
  .xtab__ext{display:none}
  .qq__dock:hover .xtab__body{width:44px}
}

/* On phones the bottom bar carries Free Quote, so the side tab steps aside
   rather than sitting over the copy. */
@media (max-width:560px){.qq__dock{display:none}}
.qq__scrim{position:fixed;inset:0;background:rgba(0,0,0,.76);z-index:96;opacity:0;visibility:hidden;transition:opacity var(--t),visibility var(--t)}
.qq__panel{position:fixed;top:0;right:0;bottom:0;width:min(520px,94vw);z-index:97;background:var(--panel);border-left:3px solid var(--or);padding:20px 24px 28px;overflow-y:auto;overscroll-behavior:contain;clip-path:inset(0 0 0 100%);pointer-events:none;transition:clip-path .32s cubic-bezier(.2,.6,.3,1)}
.qq__toggle:checked ~ .qq .qq__panel{clip-path:inset(0 0 0 0);pointer-events:auto}
.qq__toggle:checked ~ .qq .qq__scrim{opacity:1;visibility:visible}
.qq__toggle:checked ~ .qq .qq__dock{opacity:0;visibility:hidden}
.qq__close{position:sticky;float:right;top:0;margin:-4px -4px 0 0;z-index:2;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;width:44px;height:44px;border-radius:50%;border:1px solid var(--panel-line);color:var(--white)}
.qq__close:hover{border-color:var(--or);color:var(--or-lift)}
.qq__eyebrow{font-family:var(--cond);font-weight:700;font-size:14px;letter-spacing:.22em;text-transform:uppercase;color:var(--or-lift);margin:0 0 10px}
.qq__title{font-family:var(--disp);font-weight:400;font-size:clamp(26px,2.4vw,33px);line-height:1.04;text-transform:uppercase;color:var(--white);margin:0 0 11px}
.qq__intro{font-size:14.5px;line-height:1.6;color:var(--t-body);margin-bottom:22px}
.qq__call{display:flex;align-items:center;gap:14px;padding:16px 18px;background:var(--bg);border:1px solid var(--panel-line);border-left:3px solid var(--or);border-radius:0 var(--r) var(--r) 0;min-width:0;transition:border-color var(--t)}
.qq__call:hover{border-color:var(--or)}
.qq__callicon{display:inline-flex;align-items:center;justify-content:center;flex:none;width:44px;height:44px;border-radius:50%;background:var(--or);color:var(--white);font-size:17px}
.qq__call small{display:block;font-size:12.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--t-mute);margin-bottom:3px}
.qq__call b{font-family:var(--disp);font-weight:400;font-size:24px;letter-spacing:.03em;color:var(--white);overflow-wrap:anywhere}
.qq__form{display:block}
.qq__form > .field{min-width:0}
.qq__form > .btn,.qq__form > .qq__call,.qq__form > .qq__fine{grid-column:1/-1}
@media (max-width:480px){.qq__form{grid-template-columns:minmax(0,1fr)}}
.qq__fine{font-size:12.5px;line-height:1.55;color:var(--t-mute);margin:0}
.qqbadge{position:relative;overflow:hidden;margin-top:26px;background:var(--bg);border:1px solid var(--or-ring);border-radius:var(--r);padding:22px 22px 20px}
.qqbadge::before{content:"";position:absolute;top:-78px;right:-56px;width:200px;height:200px;background:radial-gradient(circle,rgba(255,106,0,.32) 0%,rgba(255,106,0,0) 68%);pointer-events:none}
.qqbadge > *{position:relative}
.qqbadge__label{font-family:var(--cond);font-weight:700;font-size:13px;letter-spacing:.2em;text-transform:uppercase;color:var(--or-lift);margin:0 0 10px}
.qqbadge__title{font-family:var(--cond);text-transform:uppercase;margin:0 0 18px}
.qqbadge__title strong{display:block;font-family:var(--disp);font-weight:400;font-size:30px;line-height:1;color:var(--or)}
.qqbadge__title span{display:block;margin-top:7px;font-weight:700;font-size:18px;line-height:1.14;color:var(--white);letter-spacing:.03em}
.qqbadge__list{display:flex;flex-direction:column;gap:10px}
.qqbadge__list li{display:flex;gap:11px;align-items:flex-start;font-size:14px;line-height:1.5;color:var(--t-body)}
.qqbadge__list i{color:var(--or);font-size:15px;margin-top:3px;flex:none}

/* ---------- Mobile action bar and back to top ---------- */
.mbar{display:none}
@media (max-width:860px){
  .mbar{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1px;position:fixed;left:0;right:0;bottom:0;z-index:75;background:var(--panel-line);border-top:1px solid var(--panel-line)}
  .mbar__act{display:inline-flex;align-items:center;justify-content:center;gap:10px;min-height:60px;cursor:pointer;font-family:var(--cond);font-weight:700;font-size:17px;letter-spacing:.1em;text-transform:uppercase}
