}
.totop{position:fixed;left:18px;bottom:18px;z-index:72;display:inline-flex;align-items:center;justify-content:center;width:50px;height:50px;cursor:pointer;background:var(--panel);border:1px solid var(--panel-line);border-radius:50%;color:var(--white);font-size:17px;transition:background var(--t),border-color var(--t)}
.totop:hover{background:var(--or);border-color:var(--or)}
@media (max-width:860px){.totop{display:none}}


/* ==========================================================================
   PROMOTION  ·  Demolition & removal from $15,999*
   One shared style for every placement: header banner, offer section,
   pre-footer CTA and the enquiry forms. The promo blocks are orange-led so
   they never read as an ordinary charcoal section.
   The price and terms are marked with .promo-price and .promo-terms so they
   can be swapped from one global block in the Nifty dashboard.
   ========================================================================== */
.promo-price{font-family:var(--disp);font-weight:400;color:var(--or);white-space:nowrap;letter-spacing:.01em}
.promo-ast{font-size:.55em;vertical-align:.7em;margin-left:.04em}
.promo-terms{font-size:12.5px;line-height:1.55;color:var(--t-mute);margin:0}
.promo-flag{display:inline-flex;align-items:center;gap:9px;font-family:var(--cond);font-weight:800;font-size:14px;letter-spacing:.14em;text-transform:uppercase;color:var(--white);background:var(--or);padding:7px 15px 6px;border-radius:999px;margin:0 0 16px;box-shadow:0 0 0 4px rgba(255,106,0,.18)}
.promo-flag i{font-size:12px}

/* 1. Header banner */
.promobar{position:relative;display:block;overflow:hidden;color:var(--bg);background:linear-gradient(100deg,#FF6A00 0%,#FF8A33 50%,#FF6A00 100%);border-bottom:2px solid #000;transition:filter var(--t)}
.promobar::before{content:"";position:absolute;inset:0;pointer-events:none;opacity:.55;background:radial-gradient(circle at 20% 30%,rgba(0,0,0,.18) 0 1.4px,transparent 2.4px) 0 0/22px 19px}
.promobar::after{content:"";position:absolute;top:0;bottom:0;left:-140px;width:90px;background:linear-gradient(90deg,transparent,rgba(255,255,255,.38),transparent);transform:skewX(-20deg);animation:promoShine 7s ease-in-out 1.5s infinite;pointer-events:none}
@keyframes promoShine{0%,72%{left:-140px}100%{left:110%}}
.promobar:hover{filter:brightness(1.05)}
.promobar .container{position:relative;z-index:1;display:flex;align-items:center;justify-content:center;gap:12px 28px;min-height:76px;padding-top:10px;padding-bottom:10px;flex-wrap:wrap}
.promobar__text{display:flex;flex-direction:column;align-items:flex-start;min-width:0}
.promobar__msg{font-family:var(--disp);font-size:clamp(19px,1.7vw,28px);line-height:1.15;text-transform:uppercase;letter-spacing:.02em;color:var(--bg)}
.promobar__plate{display:inline-block;background:var(--bg);padding:2px 12px 0;margin:0 .12em;border-radius:4px;transform:skewX(-8deg);box-shadow:3px 3px 0 rgba(0,0,0,.25);vertical-align:-.08em}
.promobar__plate .promo-price{display:inline-block;transform:skewX(8deg);font-size:1.3em;line-height:1.05}
.promobar__tail{white-space:nowrap}
.promobar__fine{font-size:12px;font-weight:600;line-height:1.4;color:#2A1608;margin-top:5px}
.promobar__btn{display:inline-flex;align-items:center;gap:10px;flex:none;min-height:48px;padding:10px 24px;background:var(--bg);color:var(--white);border-radius:var(--r-sm);font-family:var(--cond);font-weight:700;font-size:17px;letter-spacing:.1em;text-transform:uppercase;transition:background var(--t),color var(--t)}
.promobar__btn i{color:var(--or);transition:transform var(--t)}
.promobar:hover .promobar__btn{background:var(--white);color:var(--bg)}
.promobar:hover .promobar__btn i{transform:translateX(4px)}
@media (max-width:760px){
  .promobar .container{gap:10px 14px;min-height:0;padding-top:12px;padding-bottom:12px}
  .promobar__text{align-items:center;text-align:center;flex:1 1 100%}
  .promobar__tail{display:none}
  .promobar__btn{min-height:44px;font-size:15px;padding:9px 20px}
}

/* 2. Offer section */
.promo{position:relative;overflow:hidden;background:#0A0A0A;padding-block:clamp(72px,9vw,132px);border-top:5px solid var(--or);border-bottom:5px solid var(--or)}
.promo__media{position:absolute;inset:0;z-index:0}
.promo__media img{width:100%;height:100%;object-fit:cover;object-position:center 45%;filter:contrast(1.1) saturate(1.05)}
.promo__media::after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(8,8,8,.96) 0%,rgba(8,8,8,.88) 44%,rgba(8,8,8,.5) 100%),radial-gradient(900px 520px at 18% 115%,rgba(255,106,0,.3),transparent 70%)}
.promo__slab{position:absolute;z-index:0;top:0;bottom:0;right:0;width:38%;background:linear-gradient(160deg,#FF8A33 0%,#FF6A00 45%,#C24400 100%);clip-path:polygon(26% 0,100% 0,100% 100%,0 100%)}
.promo__slab::before{content:"";position:absolute;inset:0;opacity:.5;background:radial-gradient(circle at 30% 40%,rgba(0,0,0,.2) 0 1.5px,transparent 2.5px) 0 0/26px 23px}
.promo .container{position:relative;z-index:1}
.promo__grid{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,.7fr);gap:clamp(36px,5vw,90px);align-items:center}
.promo__main{min-width:0}
.promo__title{font-size:clamp(40px,4.7vw,76px);line-height:.98;color:var(--white);margin:0 0 22px;text-shadow:0 6px 30px rgba(0,0,0,.6)}
.promo__title em{display:inline;font-style:normal}
.promo__pricing{font-family:var(--disp);text-transform:uppercase;font-size:clamp(24px,2.4vw,38px);line-height:1.1;color:var(--white);margin:0 0 20px;letter-spacing:.02em}
.promo__pricing .promo-price{font-size:1.9em;display:inline-block;vertical-align:-.12em;text-shadow:0 0 34px rgba(255,106,0,.5)}
.promo__copy{font-size:clamp(16.5px,.45vw + 15px,19px);line-height:1.6;color:#E4E4E4;max-width:60ch;margin:0 0 28px}
.promo__act{display:flex;flex-wrap:wrap;gap:14px;margin-bottom:18px}
.promo__main .promo-terms{max-width:74ch;color:#ABABAB;padding-left:14px;border-left:2px solid var(--or)}
.promo__ticket{position:relative;min-width:0;background:var(--bg);border-radius:var(--r);padding:32px 30px 28px;box-shadow:0 34px 70px -24px rgba(0,0,0,.85);transform:rotate(-2deg);text-align:center}
.promo__ticket::before,.promo__ticket::after{content:"";position:absolute;top:52%;width:26px;height:26px;border-radius:50%;background:var(--or)}
.promo__ticket::before{left:-13px}.promo__ticket::after{right:-13px}
.promo__ticket-label{font-family:var(--cond);font-weight:800;font-size:clamp(17px,1.3vw,21px);letter-spacing:.14em;text-transform:uppercase;color:var(--white);margin:0}
.promo__ticket-from{font-family:var(--cond);font-weight:700;font-size:16px;letter-spacing:.3em;text-transform:uppercase;color:var(--t-mute);margin:10px 0 0}
.promo__ticket-price{font-size:clamp(70px,7vw,122px);line-height:1;margin:2px 0 8px}
.promo__ticket-price .promo-price{text-shadow:0 0 40px rgba(255,106,0,.45)}
.promo__ticket-fine{font-size:12px;line-height:1.45;color:var(--t-mute);margin:0 auto 20px;max-width:30ch}
.promo__trust{display:flex;flex-direction:column;gap:12px;border-top:2px dashed var(--panel-line);padding-top:20px;text-align:left}
.promo__trust li{display:flex;align-items:center;gap:12px;font-family:var(--cond);font-weight:700;font-size:17px;letter-spacing:.06em;text-transform:uppercase;color:var(--white)}
.promo__trust i{display:inline-flex;align-items:center;justify-content:center;width:34px;height:34px;border-radius:50%;background:var(--or);color:var(--white);font-size:14px;flex:none}
@media (max-width:1080px){
  .promo__grid{grid-template-columns:minmax(0,1fr)}
  .promo__slab{display:none}
  .promo__ticket{max-width:460px;width:100%;margin-inline:auto;transform:none;border:3px solid var(--or);box-shadow:0 0 0 6px rgba(255,106,0,.18),0 30px 60px -24px rgba(255,106,0,.55)}
  .promo__ticket::before,.promo__ticket::after{background:#0A0A0A;border:3px solid var(--or)}
}
@media (max-width:560px){.promo__act .btn{width:100%}.promo__ticket{padding:28px 20px 24px}}

/* 3. Pre-footer CTA */
.prefoot{position:relative;overflow:hidden;background:#141414;border-top:6px solid var(--or);padding-block:clamp(48px,5vw,72px) clamp(26px,3vw,36px)}
.prefoot__media{position:absolute;inset:0;z-index:0}
.prefoot__media img{width:100%;height:100%;object-fit:cover;filter:grayscale(.85) contrast(1.15) brightness(.85)}
.prefoot__media::after{content:"";position:absolute;inset:0;background:
  repeating-linear-gradient(90deg,rgba(255,255,255,.025) 0 1px,transparent 1px 5px),
  linear-gradient(90deg,rgba(14,14,14,.95) 0%,rgba(14,14,14,.86) 55%,rgba(255,106,0,.55) 100%)}
.prefoot .container{position:relative;z-index:1}
.prefoot__grid{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:28px 56px;align-items:center;min-height:170px}
.prefoot__text{min-width:0}
.prefoot__title{font-size:clamp(40px,4.6vw,72px);line-height:.98;color:var(--white);margin:0 0 10px}
.prefoot__sub{font-family:var(--disp);text-transform:uppercase;font-size:clamp(22px,2.2vw,34px);line-height:1.1;color:var(--white);margin:0 0 14px;letter-spacing:.02em}
.prefoot__sub .promo-price{font-size:1.4em}
.prefoot__copy{font-size:clamp(16px,.4vw + 15px,18px);color:#DADADA;max-width:62ch;margin:0}
.prefoot__act{display:flex;flex-direction:column;gap:12px;min-width:min(100%,280px)}
.prefoot__terms{margin-top:clamp(22px,2.5vw,32px);padding-top:14px;border-top:1px solid rgba(255,255,255,.12);color:#A3A3A3;max-width:none}
@media (max-width:860px){.prefoot__grid{grid-template-columns:minmax(0,1fr)}.prefoot__act .btn{width:100%}}

/* 4. Enquiry forms */
.form-promo{background:rgba(255,106,0,.08);border:1px solid var(--or-ring);border-left:3px solid var(--or);border-radius:var(--r-sm);padding:10px 13px;margin:0 0 13px}
.form-promo > p:first-child{margin:0 0 7px;font-size:14.5px;line-height:1.5;color:var(--t-body)}
.form-promo .promo-price{font-size:1.4em}
.form-promo .promo-terms{font-size:11.5px}
.opt{font-family:'Inter',sans-serif;font-weight:500;font-size:12px;letter-spacing:0;text-transform:none;color:var(--t-mute)}
.field input[type=file]{padding:9px 10px;min-height:52px;cursor:pointer;color:var(--t-mute);font-size:14px}
.field input[type=file]::file-selector-button{margin-right:12px;padding:8px 14px;border:0;border-radius:var(--r-sm);background:var(--or);color:var(--white);font-family:var(--cond);font-weight:700;font-size:14px;letter-spacing:.08em;text-transform:uppercase;cursor:pointer}
.heroform .promo-flag,.formcard .promo-flag,.qq__panel .promo-flag{font-size:12.5px;padding:6px 13px 5px;margin-bottom:12px}
.qq__panel .btn{width:100%}
.qq__panel .qq__call{margin-top:14px}
.qq__panel .qq__fine{margin-top:12px}

/* Region line (six named regions) */
.proof__item--regions{flex:2 1 360px}
.onecta__chips li.onecta__chip--regions{white-space:normal}
.xtab__ext span.xtab__regions{font-size:11.5px;line-height:1.25;gap:5px}

/* Areas: six-region heading and the NSW region map */
.regions-h{font-size:clamp(30px,3vw,46px);line-height:1.08}
.regions-h i{font-style:normal;color:var(--or);opacity:.7;padding-inline:.06em}
.nswmap{position:relative;margin:34px 0 0;width:100%;aspect-ratio:600/640;background:#101010;border:1px solid var(--panel-line);border-radius:var(--r);overflow:hidden;box-shadow:0 30px 60px -30px rgba(0,0,0,.9),inset 0 0 0 1px rgba(255,106,0,.06)}
.nswmap__svg{position:absolute;inset:0;width:100%;height:100%}
.nswmap__inset{position:absolute;left:14px;top:14px;width:clamp(78px,18%,112px);padding:6px 6px 4px;background:rgba(14,14,14,.85);border:1px solid var(--panel-line);border-radius:6px;text-align:center}
.nswmap__inset svg{width:100%;height:auto;display:block}
.nswmap__inset span{display:block;font-family:var(--cond);font-weight:800;font-size:11px;letter-spacing:.24em;color:var(--t-mute);margin-top:2px}
.nswmap__brand{position:absolute;right:14px;bottom:14px;display:flex;align-items:center;gap:10px;max-width:58%;padding:8px 12px 8px 8px;background:rgba(14,14,14,.9);border:1px solid var(--or);border-radius:6px;box-shadow:0 0 22px -6px var(--or-glow)}
.nswmap__brand img{width:clamp(64px,9vw,96px);height:auto;flex:none}
.nswmap__brand span{font-family:var(--cond);font-weight:800;font-size:clamp(11px,.9vw,13.5px);letter-spacing:.08em;text-transform:uppercase;color:var(--white);line-height:1.15;min-width:0}
/* Pins: an orange drop holding the excavator mark, with the region name beside it. */
.mpin{position:absolute;z-index:2;display:flex;align-items:center;gap:6px;transform:translate(-14px,-100%);text-decoration:none}
.mpin--l{flex-direction:row-reverse;transform:translate(calc(-100% + 14px),-100%)}
.mpin__drop{position:relative;flex:none;width:28px;height:28px;border-radius:50% 50% 50% 0;transform:rotate(-45deg);background:var(--or);box-shadow:0 0 0 3px rgba(14,14,14,.85),0 6px 14px -4px rgba(0,0,0,.8),0 0 16px rgba(255,106,0,.55);transition:transform var(--t)}
.mpin__drop::after{content:"";position:absolute;left:-3px;bottom:-3px;width:6px;height:6px;border-radius:50%;background:var(--white);box-shadow:0 0 0 3px rgba(255,106,0,.35)}
.mpin__ico{position:absolute;inset:3px;border-radius:50%;background:#0E0E0E url("data:image/svg+xml;base64,") center 40%/86% auto no-repeat;transform:rotate(45deg)}
.mpin__name{margin-bottom:22px;padding:3px 8px 2px;background:rgba(14,14,14,.92);border:1px solid var(--panel-line);border-left:2px solid var(--or);border-radius:3px;font-family:var(--cond);font-weight:800;font-size:clamp(11.5px,1vw,14px);letter-spacing:.06em;text-transform:uppercase;color:var(--white);white-space:nowrap;line-height:1.2;transition:border-color var(--t),color var(--t)}
.mpin--l .mpin__name{border-left:1px solid var(--panel-line);border-right:2px solid var(--or)}
.mpin:hover .mpin__drop{transform:rotate(-45deg) scale(1.15)}
.mpin:hover .mpin__name{color:var(--or-lift);border-color:var(--or)}
@media (max-width:420px){.mpin__drop{width:22px;height:22px}.mpin{transform:translate(-11px,-100%)}.mpin--l{transform:translate(calc(-100% + 11px),-100%)}.mpin__name{margin-bottom:16px;padding:2px 6px 1px}}

@media print{
  .util,.hdr,.qq,.qq__dock,.mbar,.totop,.hero__media,.dust,.skyline,.promobar{display:none!important}
  body{background:#fff;color:#000}
  .reveal{animation:none;opacity:1}
}

/* Quick quote drawer: the panel is a fixed height overlay, so its content has
   to earn its space. These only apply inside the drawer and leave the same form
   on the page untouched. */
.qq__panel .leadform .field{margin-bottom:10px}
.qq__panel .leadform label{margin-bottom:5px}
.qq__panel .promo-terms{font-size:11px;line-height:1.45}
.qq__panel .leadform textarea{min-height:76px}
/* The drawer is taller than most laptop screens, so the submit button used to
   sit below the fold and the panel read as cut off. Pinning it to the bottom of
   the panel keeps it reachable at any scroll position, and the fade above it
   shows there is more form behind it. */
.qq__panel .leadform button[type="submit"]{position:sticky;bottom:0;z-index:3;width:100%}
.qq__panel .leadform button[type="submit"]::before{content:"";position:absolute;
  left:0;right:0;bottom:100%;height:18px;pointer-events:none;
  background:linear-gradient(to top,var(--panel),transparent)}


/* ==========================================================================
   Internal page components, built on the approved home-v3_1 token system.
   Nothing here introduces a new colour, typeface, radius or motion rule: every
   value resolves to a token already declared in the approved shell.
   ========================================================================== */

/* The services mega menu now carries five families rather than eight. This is
   the smallest grid change that fits them, as section 5 of the brief allows. */
.mega--five{grid-template-columns:repeat(5,minmax(0,1fr));gap:26px 22px}
@media (max-width:1320px){ .mega--five{grid-template-columns:repeat(3,minmax(0,1fr))} }
@media (max-width:980px){ .mega--five{grid-template-columns:repeat(2,minmax(0,1fr))} }
@media (max-width:900px){ .mega--five{grid-template-columns:minmax(0,1fr)} }

/* Header height, published so sticky children stack beneath it and anchor
   targets clear the chrome. Measured from the rendered approved shell. */
:root{ --hdr-h:76px; --promo-h:0px; }
@media (min-width:901px){ :root{ --hdr-h:92px } }

/* ---------------------------------------------------------------- breadcrumb */
.crumb{background:var(--bg-deep);border-bottom:1px solid var(--panel-line)}
.crumb ol{
  list-style:none;margin:0;padding:13px 0;display:flex;flex-wrap:wrap;align-items:center;
  gap:7px;font-family:var(--cond);font-size:14px;letter-spacing:.02em;
}
.crumb li{display:flex;align-items:center;gap:7px;color:var(--t-mute)}
.crumb li+li::before{content:"";width:5px;height:5px;border-right:1.5px solid var(--t-mute);
  border-top:1.5px solid var(--t-mute);transform:rotate(45deg);display:inline-block}
.crumb a{color:var(--t-body);text-decoration:none;transition:color var(--t);
  min-height:24px;display:inline-flex;align-items:center}
.crumb a:hover{color:var(--or-lift)}
.crumb a:focus-visible{outline:3px solid var(--or);outline-offset:3px;border-radius:var(--r-sm)}
.crumb [aria-current="page"]{color:var(--white);font-weight:600}
@media (max-width:560px){ .crumb li.crumb--fold{display:none} }

/* anchor targets must clear the sticky header */
[id]{scroll-margin-top:calc(var(--hdr-h) + 20px)}

/* ------------------------------------------------------------- page sections */
.phead{margin:0 0 clamp(26px,3vw,44px);max-width:74ch}
.phead .eyebrow{margin-bottom:12px}
.prose{color:var(--t-body);font-size:clamp(15.5px,1.05vw,17px);line-height:1.72}
.section--light .prose{color:var(--l-body)}
.prose p{margin:0 0 15px}
.prose p:last-child{margin-bottom:0}
.prose ul{margin:0 0 15px;padding:0;list-style:none}
.prose li{position:relative;padding-left:22px;margin:0 0 10px;line-height:1.66}
.prose li::before{content:"";position:absolute;left:0;top:.72em;width:9px;height:2px;background:var(--or)}
.prose strong{color:var(--white);font-weight:600}
.section--light .prose strong{color:var(--l-head)}

/* split: copy beside a contained visual */
.split{display:grid;grid-template-columns:1.08fr .92fr;gap:clamp(28px,4vw,62px);align-items:start}
.split--mediafirst .split__media{order:-1}
.split__media img{width:100%;height:auto;display:block;border-radius:var(--r);border:1px solid var(--panel-line)}
.section--light .split__media img{border-color:var(--light-line)}
.split__cap{margin:12px 0 0;padding-left:13px;border-left:2px solid var(--or);
  color:var(--t-mute);font-size:13.5px;line-height:1.55}
.section--light .split__cap{color:var(--l-mute)}
@media (max-width:900px){ .split{grid-template-columns:minmax(0,1fr)}
  .split--mediafirst .split__media{order:0} }

/* key facts strip under a hero */
.kfacts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1px;background:var(--panel-line);
  border:1px solid var(--panel-line);border-radius:var(--r);overflow:hidden;margin-top:clamp(22px,2.6vw,34px)}
.kfacts>div{background:rgba(14,14,14,.86);padding:16px 20px;backdrop-filter:blur(2px)}
.kfacts dt{margin:0 0 4px;font-family:var(--cond);font-size:12px;font-weight:700;
  letter-spacing:.2em;text-transform:uppercase;color:var(--or-lift)}
.kfacts dd{margin:0;color:var(--white);font-size:14.5px;line-height:1.5}
@media (max-width:760px){ .kfacts{grid-template-columns:minmax(0,1fr)} }

/* sticky in page rail */
.pnav{position:sticky;top:var(--hdr-h);z-index:40;background:var(--bg-band);
  border-bottom:1px solid var(--panel-line)}
.pnav ul{list-style:none;margin:0;padding:0;display:flex;gap:4px;overflow-x:auto;
  scrollbar-width:none;-webkit-overflow-scrolling:touch}
.pnav ul::-webkit-scrollbar{display:none}
.pnav a{display:inline-flex;align-items:center;min-height:46px;padding:0 15px;white-space:nowrap;
  font-family:var(--cond);font-weight:600;font-size:13.5px;letter-spacing:.13em;text-transform:uppercase;
  color:var(--t-body);text-decoration:none;border-bottom:2px solid transparent;transition:color var(--t),border-color var(--t)}
.pnav a:hover{color:var(--white);border-bottom-color:var(--or)}
.pnav a:focus-visible{outline:3px solid var(--or);outline-offset:-3px}

/* data table */
.dtable{width:100%;border-collapse:collapse;font-size:15px}
.dtable th,.dtable td{text-align:left;vertical-align:top;padding:14px 16px;
  border-bottom:1px solid var(--panel-line)}
.section--light .dtable th,.section--light .dtable td{border-bottom-color:var(--light-line)}
.dtable thead th{font-family:var(--cond);font-size:12.5px;font-weight:700;letter-spacing:.17em;
  text-transform:uppercase;color:var(--or-lift);border-bottom-width:2px}
.section--light .dtable thead th{color:var(--or-ink)}
.dtable tbody th{font-weight:600;color:var(--white);width:30%}
.section--light .dtable tbody th{color:var(--l-head)}
.dtable td{color:var(--t-body)}
.section--light .dtable td{color:var(--l-body)}
@media (max-width:680px){
  .dtable,.dtable tbody,.dtable tr,.dtable th,.dtable td{display:block;width:auto}
  .dtable thead{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
  .dtable tr{border:1px solid var(--panel-line);border-radius:var(--r);padding:6px 2px;margin:0 0 12px}
  .section--light .dtable tr{border-color:var(--light-line)}
  .dtable th,.dtable td{border-bottom:0;padding:8px 15px}
  .dtable tbody th{width:auto;padding-bottom:2px}
}

/* callout */
.note{border-left:3px solid var(--or);background:var(--or-wash);padding:20px 24px;border-radius:0 var(--r) var(--r) 0}
.note h3,.note h4{margin:0 0 8px;font-family:var(--cond);font-weight:700;font-size:17px;
  letter-spacing:.05em;text-transform:uppercase;color:var(--white)}
.section--light .note h3,.section--light .note h4{color:var(--l-head)}
.note p{margin:0 0 10px;font-size:15px;line-height:1.62;color:var(--t-body)}
.section--light .note p{color:var(--l-body)}
.note p:last-child{margin-bottom:0}

/* FAQ, details based so it works with scripts stripped */
.faq{border-top:1px solid var(--panel-line)}
.section--light .faq{border-top-color:var(--light-line)}
.faq details{border-bottom:1px solid var(--panel-line)}
.section--light .faq details{border-bottom-color:var(--light-line)}
.faq summary{
  list-style:none;cursor:pointer;padding:19px 44px 19px 0;position:relative;min-height:44px;
  font-family:var(--cond);font-weight:600;font-size:clamp(17px,1.4vw,19px);color:var(--white);
}
.section--light .faq summary{color:var(--l-head)}
.faq summary::-webkit-details-marker{display:none}
.faq summary::after{content:"";position:absolute;right:14px;top:50%;width:10px;height:10px;
  border-right:2px solid var(--or);border-bottom:2px solid var(--or);
  transform:translateY(-70%) rotate(45deg);transition:transform var(--t)}
.faq details[open] summary::after{transform:translateY(-30%) rotate(-135deg)}
.faq summary:focus-visible{outline:3px solid var(--or);outline-offset:-3px}
.faq .faq__a{padding:0 0 20px;color:var(--t-body);font-size:15.5px;line-height:1.7;max-width:84ch}
.section--light .faq .faq__a{color:var(--l-body)}

/* inline band */
.band{background:var(--bg-band);border-top:1px solid var(--panel-line);border-bottom:1px solid var(--panel-line)}
.band__in{display:flex;flex-wrap:wrap;gap:22px;align-items:center;justify-content:space-between;
  padding:clamp(26px,3vw,40px) 0}
.band__t{margin:0;font-family:var(--disp);font-size:clamp(23px,2.4vw,33px);line-height:1.1;
  color:var(--white);text-transform:uppercase;letter-spacing:.005em}
.band__s{margin:7px 0 0;color:var(--t-body);font-size:15px;max-width:62ch}

/* related links row */
.srow{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(236px,100%),1fr));gap:14px}
.srow a{
  display:block;padding:18px 20px;border:1px solid var(--panel-line);border-radius:var(--r);
  background:var(--panel);text-decoration:none;transition:border-color var(--t),transform var(--t),background var(--t);
}
.section--light .srow a{background:var(--white);border-color:var(--light-line)}
.srow a:hover{border-color:var(--or);transform:translateY(-2px)}
.srow a:focus-visible{outline:3px solid var(--or);outline-offset:2px}
.srow b{display:block;font-family:var(--cond);font-weight:600;font-size:17px;color:var(--white);margin-bottom:4px}
.section--light .srow b{color:var(--l-head)}
.srow span{display:block;color:var(--t-mute);font-size:13.5px;line-height:1.5}
.section--light .srow span{color:var(--l-mute)}

/* section heading block used on internal pages */
.shead{display:flex;flex-wrap:wrap;gap:18px 38px;align-items:flex-end;justify-content:space-between;
  margin:0 0 clamp(24px,3vw,40px)}
.shead h2{margin:0;max-width:22ch}
.shead__note{margin:0;color:var(--t-mute);font-size:15px;line-height:1.6;max-width:52ch}
.section--light .shead__note{color:var(--l-mute)}

/* smaller section heading, used by the related blocks */
.h2--sm{font-size:clamp(23px,2.3vw,32px)}

/* spacing utilities, so generated markup carries no inline style attributes */
.mt-22{margin-top:22px}
.mt-24{margin-top:24px}
.mt-28{margin-top:28px}
.mt-34{margin-top:34px;border-radius:var(--r)}
.sep-48{margin:48px 0 20px}

/* the optional marker on a non required field, client item 6 */
.opt{color:var(--t-mute);font-weight:500;font-size:.92em}


/* ==========================================================================
   ACCESSIBILITY CORRECTIONS to the approved home-v3_1 design system.

   The operator brief sets the authoritative source order for this run, and
   applicable law and regulator requirements sit above the operator instruction
   in it. These corrections exist because the approved system, as supplied,
   does not meet WCAG 2.2 AA. Each one is the smallest change that fixes the
   measured failure, and each is listed in the approval document for a decision.

   Deleting this one file restores the approved appearance exactly.
   ========================================================================== */

/* --------------------------------------------------------------------------
   1. TEXT ON THE BRAND ORANGE.
   Measured: #FFFFFF on #FF6A00 is 2.87:1. That is below the 4.5:1 floor for
   normal text AND below the 3:1 floor for large text, so every orange button
   in the system fails, including the primary conversion button.
   Correction: the label becomes the core background charcoal #0E0E0E, which
   measures 6.72:1 on the same orange. The fill, the glow, the geometry, the
   hover lift and the pressed state are all unchanged.
   Alternative, if the client prefers a white label: the fill has to darken to
   about #B84A00, which measures 5.23:1 but is a visibly different orange.
   -------------------------------------------------------------------------- */
.btn--primary,
.util__quote,
.mbar__act--quote,
.fam__icon,
.step__num,
/* the bypass link is orange filled and only visible when focused, so it needs
   the same correction as every other orange control */
.skip,
/* the promotional pill is filled with the brand orange and measured 3.01:1
   with a white label, below the 4.5:1 floor for text at its size */
.promo-flag{ color:#0E0E0E }
/* NOT .promobar__btn and NOT .xtab__body: both sit on a dark fill, not on the
   orange, and were measured to confirm it. A blanket rule made the promo bar
   button charcoal on charcoal and invisible. */
.btn--primary:hover,
.btn--primary:active,
.util__quote:hover,
.mbar__act--quote:hover{ color:#0E0E0E }
/* keep icons inside those controls on the same corrected colour */
.btn--primary i,.util__quote i,.mbar__act--quote i{ color:inherit }

/* --------------------------------------------------------------------------
   2. MOBILE MENU CLOSE CONTROL.
   Measured 46 by 20 CSS px. The stylesheet asks for 46 by 46, but the control
   is a column flex item and was being shrunk. SC 2.5.8 requires 24 by 24.
   -------------------------------------------------------------------------- */
.navclose{ flex:none;
  /* SC 2.5.8. The shell sets height:46px but the element is a flex item with
     flex:none in a column, so it collapses to its 19px line box and the mobile
     menu close control falls under the 24px floor. Measured at 390px. */
  min-height:46px; box-sizing:border-box }

/* --------------------------------------------------------------------------
   3. SMALL TEXT ON THE LIGHT SURFACE.
   --or #FF6A00 measures 2.61:1 on the light surface #F5F4F1 and must not carry
   normal sized text there. --or-ink #B84A00 measures 4.75:1 and does.
   -------------------------------------------------------------------------- */
:root{ --or-on-light:#B84A00 }
.section--light .tlink{ color:var(--or-on-light) }

/* --------------------------------------------------------------------------
   4. TAP TARGETS BELOW THE 24 BY 24 FLOOR, SC 2.5.8.
   Both measured on the rendered page, both inherited from the approved shell.
   Neither change is visible: the caret gains two pixels of width and the build
   credit gains two pixels of height, inside existing padding.
   -------------------------------------------------------------------------- */
.subcaret{ min-width:24px }          /* measured 22 by 44 */
.ftr__built{ min-height:24px;display:inline-flex;align-items:center }  /* measured 214 by 22 */


/* ---- page specific ---- */

.nav__link--on{color:var(--or-lift)!important}

/* ---- shared typographic hero for the supporting routes ---- */
.shero{background:var(--bg-deep);border-bottom:1px solid var(--panel-line);
  padding:clamp(34px,4vw,60px) 0 clamp(30px,3.4vw,48px)}
.shero h1{margin:10px 0 16px;max-width:22ch}
.shero__lede{margin:0;max-width:66ch;color:var(--t-body);
  font-size:clamp(15.5px,1.1vw,17.5px);line-height:1.66}
.shero__act{display:flex;flex-wrap:wrap;gap:14px;align-items:center;margin-top:24px}
.ilist{display:grid;gap:1px;background:var(--panel-line);border:1px solid var(--panel-line);
  border-radius:var(--r);overflow:hidden}
.ilist__g{background:var(--bg);padding:clamp(18px,2vw,26px)}
.ilist__g > h3{margin:0 0 4px;font-family:var(--cond);font-weight:700;
  font-size:clamp(19px,1.6vw,22px);color:var(--white)}
.ilist__g > p{margin:0 0 14px;color:var(--t-mute);font-size:14.5px;line-height:1.6}
.ilist__l{list-style:none;margin:0;padding:0;display:grid;gap:8px}
.ilist__l li{margin:0}
.ilist__l a{display:flex;gap:9px;align-items:baseline;color:var(--t-body);font-size:15px;
  line-height:1.5;text-decoration:none;min-height:24px}
.ilist__l a > span{min-width:0}
.ilist__l a:hover{color:var(--white)}
.ilist__l i{color:var(--or);font-size:11px;flex:none}
.ilist__g--two .ilist__l{grid-template-columns:repeat(auto-fit,minmax(min(230px,100%),1fr))}
.cgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(260px,100%),1fr));
  gap:clamp(16px,1.8vw,24px)}
.cgrid > div{min-width:0;background:var(--panel);border:1px solid var(--panel-line);
  border-radius:var(--r);padding:clamp(18px,2vw,24px)}
.cgrid h3{margin:0 0 8px;font-family:var(--cond);font-weight:700;font-size:19px;color:var(--white)}
.cgrid p{margin:0;color:var(--t-body);font-size:15px;line-height:1.62}
.cgrid a{color:var(--or-lift)}
.cgrid img{display:block;width:100%;height:auto;border-radius:6px;margin:12px 0}
.utilwrap{max-width:72ch}
.utilwrap h2{margin:34px 0 10px}
.utilwrap h3{margin:24px 0 8px}
.tag{display:inline-block;margin-left:8px;padding:2px 8px;border-radius:999px;
  background:var(--or-deep);color:#0E0E0E;font-family:var(--cond);font-weight:700;
  font-size:11.5px;letter-spacing:.06em;text-transform:uppercase;vertical-align:middle}
.note--ask{border-left:3px solid var(--or);background:var(--panel);padding:16px 18px;
  border-radius:var(--r);margin:22px 0}
.note--ask p{margin:0;color:var(--t-body);font-size:15px;line-height:1.62}
.note--ask strong{color:var(--white)}
/* A link that is the whole content of a table row header is a standalone
   target, not a link inline in a sentence, so WCAG 2.2 SC 2.5.8 applies to it.
   Measured at 19px tall before this rule. */
.dtable th a{display:inline-flex;align-items:center;min-height:24px}
